{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "train_options_table"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "London to Paris Train Options: Standard Premier",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Here are round-trip train options from London St Pancras to Paris Gare du Nord for 1 adult, departing on December 24, 2024, and returning on December 28, 2024. These options are in Standard Premier class with morning departures (before 12:00 PM) for both legs. Please note that prices for Standard Premier during the Christmas period often exceed a £300 budget.",
        "variant": "body"
      },
      "children": []
    },
    "train_options_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "operator",
            "label": "Operator"
          },
          {
            "key": "outbound_leg",
            "label": "Outbound Leg (Dep. - Arr.)"
          },
          {
            "key": "return_leg",
            "label": "Return Leg (Dep. - Arr.)"
          },
          {
            "key": "travel_time",
            "label": "Travel Time (Each Leg)"
          },
          {
            "key": "stops",
            "label": "Stops"
          },
          {
            "key": "class",
            "label": "Class"
          },
          {
            "key": "total_fare",
            "label": "Total Fare"
          }
        ],
        "rows": [],
        "domain": "booking",
        "preferredPresentation": "cards",
        "primaryColumn": "operator",
        "highlightColumns": [
          "total_fare",
          "travel_time"
        ],
        "numericColumns": [
          "total_fare"
        ]
      },
      "children": []
    }
  }
}
